import type { CourseCedLessons } from "./types";

/**
 * AP European History CED lessons — every topic from Units 1-9 of the
 * 2024-25 CED. Narratives foreground the three historical thinking
 * skills APEH scores: causation, comparison, and continuity/change
 * over time. Lessons are written so a student can answer SAQ, DBQ, and
 * LEQ prompts with specific evidence (named treaties, thinkers, dates)
 * and clear periodization.
 *
 * Worked examples model SAQ-style responses (claim + specific evidence
 * + reasoning) because that is the form most often tested and most
 * often missed by students who otherwise know the content. Selected
 * topics include inline SVG diagrams — comparison charts, timelines,
 * and map sketches — to surface visual structure (e.g., absolutism vs
 * constitutionalism, the Concert of Europe alliance system, the path
 * of the French Revolution).
 */

